请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-003

=== 用户原始指令 (query.txt) ===
整个背景图上叠文字的卡,数字会变,点一下进入专注模式

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个背景图上叠文字的卡,数字会变,点一下进入专注模式",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "focus": {
      "title": {
        "type": "string",
        "description": "专注模式卡片标题",
        "sampleValue": "专注模式"
      },
      "minutes": {
        "type": "number",
        "description": "当前计划或剩余专注时长的分钟数，运行时可变化",
        "sampleValue": 45
      },
      "unit": {
        "type": "string",
        "description": "专注时长单位",
        "sampleValue": "分钟"
      },
      "status": {
        "type": "string",
        "description": "专注状态或模式说明短句",
        "sampleValue": "轻触进入"
      },
      "actionHint": {
        "type": "string",
        "description": "进入专注模式的短提示",
        "sampleValue": "开启专注"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_focus.png",
      "description": "专注模式图标素材，适合作为专注卡片的背景视觉锚点或主识别图形。"
    }
  ]
}

